def extract_bmp_key_from_data():
    hex_clean = BMP_HEX.replace('\n', '').replace(' ', '')
    bmp_data = bytes.fromhex(hex_clean)
    
    return bmp_data[:1498]

def byte_block_swap(buf: bytes) -> bytes:
    b = bytearray(buf)
    b[68:80], b[140:152] = b[140:152], b[68:80]
    b[104:116], b[128:140] = b[128:140], b[104:116]
    return bytes(b)


def decrypt_block(data: bytes, key: bytes) -> bytes:
    key_func = lambda i: (i % 1498) % len(key) # 1565
    return bytes(b ^ key[key_func(i)] for i, b in enumerate(data))


def process_metadata(file_path: str) -> None:
    with open(file_path, 'rb') as f:
        raw = f.read()

    if len(raw) < 4:
        return

    magic = struct.unpack('<I', raw[:4])[0]

    if magic == ENCRYPTED_MAGIC:
        raw = decrypt_block(raw, extract_bmp_key_from_data())
        if struct.unpack('<I', raw[:4])[0] != UNENCRYPTED_MAGIC:
            return
        raw = byte_block_swap(raw)

    elif magic == UNENCRYPTED_MAGIC:
        raw = byte_block_swap(raw)
    else:
        return

    with open(file_path, 'wb') as f:
        f.write(raw)
    print("完事")

if __name__ == "__main__":
    process_metadata("global-metadata.dat")